+  const c = run(root, ['commit', '--task', 'T001', '--skip-oracle']);
+  assert.equal(c.status, 0, c.stderr);
+  assert.match(lastCommitMsg(root), /\[inconclusive\]$/, 'метка в сообщении коммита — видно в git log без чтения журналов');
